head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > blur]<br/>컴포넌트에서 포커스를 제거(Blur)합니다.",
    "validation" : [
        "컴포넌트에서 포커스를 제거(Blur)합니다.",
        "포커스가 컴포넌트의 날짜 편집 영역에 있었다면 onblur 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onfocus", "onblur"]);

    // comp 생성 함수 호출    
    $c.gcm.createBasicInputCalendar('', eList); 
}


scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus=====");
    wf_body_bottom.getObj("scwin").setReturnValue("1초 뒤 blur 자동 수행됨");

    // 버튼 클릭 시 즉시 포커스가 빠지는 문제를 피하기 위해 onfocus 후 1초 뒤 blur 호출
    setTimeout(function () {
        target1.blur();
    }, 1000);
}



scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur=====");
}



scwin.btn_focus_onclick = function (e) {
	target1.focus();
};
